      + 0.13 * Math.sin(nx * 3.3 + s)
      + 0.11 * Math.sin(ny * 4.1 + s * 1.7 + 1.3)
      + 0.08 * Math.sin(nz * 2.7 + s * 2.3 + 2.6)
      + 0.05 * Math.sin((nx + ny + nz) * 5.9 + s * 3.1);
