                Venus:   { a: 0.7233, L0: 181.9798, n: 1.60213034 },
                Earth:   { a: 1.0000, L0: 100.4664, n: 0.98560912 },
                Mars:    { a: 1.5237, L0: 355.4330, n: 0.52403295 },
                Ceres:   { a: 2.7675, L0: 153.9000, n: 0.21408170 },
                Jupiter: { a: 5.2034, L0:  34.3515, n: 0.08308529 },
                Saturn:  { a: 9.5371, L0:  50.0774, n: 0.03345965 },
                Uranus:  { a: 19.1913, L0: 314.0550, n: 0.01173129 },
                Neptune: { a: 30.0690, L0: 304.3487, n: 0.00598103 },
                Pluto:   { a: 39.4820, L0: 238.9288, n: 0.00397527 },
