            h('span', { 'data-tf-audio-state': tfRevealed ? 'with-explanation' : 'prompt-only', style: { fontSize: '12px', fontWeight: 700, color: controlInk } }, tfRevealed ? 'Audio includes answer & explanation' : 'Audio reads statement only (answer hidden)'),
            h('button', { type: 'button', 'data-tf-audio': true, 'aria-label': 'Read orbital intuition statement aloud', onClick: function() { speakText(tfSpeech); }, style: { minHeight: '36px', padding: '5px 10px' } }, '🔊 Listen')
