                            var gridZ = (terrainZ + terrainHalfSize) / terrainCellSize;
                            var cellX = Math.min(terrainGridSegments - 1, Math.max(0, Math.floor(gridX)));
                            var cellZ = Math.min(terrainGridSegments - 1, Math.max(0, Math.floor(gridZ)));
